use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub public_talks: i64,
    pub research_tracks: i64,
    pub dome_sections: i64,
    pub cloud_monitoring: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.public_talks >= 0 && self.research_tracks >= 0 && self.dome_sections >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub session_total: i64,
    pub open_minutes: i64,
    pub weather_minutes: i64,
    pub scheduled_minutes: i64,
    pub staff_minutes: i64,
    pub rest_breaks: i64,
    pub coordination_score: i64,
    pub observatory_mode: String,
}

pub fn score(public_talks: i64, research_tracks: i64, dome_sections: i64, cloud_monitoring: bool) -> i64 {
    let session_total = public_talks + research_tracks;
    let open_minutes = public_talks * 22 + research_tracks * 31;
    let weather_minutes = if cloud_monitoring { dome_sections * 7 } else { 0 };
    let scheduled_minutes = open_minutes + weather_minutes;
    let staff_minutes = scheduled_minutes * dome_sections;
    let rest_breaks = scheduled_minutes / 90;

    staff_minutes + rest_breaks * 13 + session_total * 5
}

pub fn handle(value: RequestInput) -> ResponseOutput {
    let open_minutes = value.public_talks * 22 + value.research_tracks * 31;
    let weather_minutes = if value.cloud_monitoring { value.dome_sections * 7 } else { 0 };
    let scheduled_minutes = open_minutes + weather_minutes;

    ResponseOutput {
        session_total: value.public_talks + value.research_tracks,
        open_minutes,
        weather_minutes,
        scheduled_minutes,
        staff_minutes: scheduled_minutes * value.dome_sections,
        rest_breaks: scheduled_minutes / 90,
        coordination_score: score(value.public_talks, value.research_tracks, value.dome_sections, value.cloud_monitoring),
        observatory_mode: if value.research_tracks > value.public_talks {
            "research_first"
        } else if value.public_talks > 0 {
            "outreach"
        } else {
            "standby"
        }
        .into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_observatory_score(a: i64, b: i64, c: i64, d: i32) -> i64 {
    score(a, b, c, d != 0)
}

