use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub arriving_hikers: i64,
    pub injured_hikers: i64,
    pub heater_packs: i64,
    pub storm_lockdown: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.arriving_hikers >= 0
            && self.injured_hikers >= 0
            && self.heater_packs >= 0
            && self.arriving_hikers.checked_add(self.injured_hikers).is_some()
            && self
                .arriving_hikers
                .checked_mul(3)
                .and_then(|arriving| {
                    self.injured_hikers
                        .checked_mul(6)
                        .and_then(|injured| arriving.checked_add(injured))
                })
                .is_some()
            && self.heater_packs.checked_mul(8).is_some()
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub hiker_total: i64,
    pub baseline_warmth: i64,
    pub lockdown_reduction: i64,
    pub required_warmth: i64,
    pub pack_capacity: i64,
    pub delivered_warmth: i64,
    pub uncovered_warmth: i64,
    pub unused_capacity: i64,
    pub shelter_state: String,
}

fn calculate(a: i64, i: i64, p: i64, storm_lockdown: bool) -> ResponseOutput {
    let hiker_total = a + i;
    let baseline_warmth = a * 3 + i * 6;
    let lockdown_reduction = if storm_lockdown { p * 2 } else { 0 };
    let required_warmth = baseline_warmth.saturating_sub(lockdown_reduction);
    let pack_capacity = p * 8;
    let delivered_warmth = required_warmth.min(pack_capacity);
    let uncovered_warmth = required_warmth - delivered_warmth;
    let unused_capacity = pack_capacity - delivered_warmth;
    let shelter_state = if uncovered_warmth == 0 {
        "covered"
    } else if storm_lockdown {
        "storm_gap"
    } else {
        "supply_gap"
    };

    ResponseOutput {
        hiker_total,
        baseline_warmth,
        lockdown_reduction,
        required_warmth,
        pack_capacity,
        delivered_warmth,
        uncovered_warmth,
        unused_capacity,
        shelter_state: shelter_state.into(),
    }
}

pub fn unused(a: i64, i: i64, p: i64, storm_lockdown: bool) -> i64 {
    calculate(a, i, p, storm_lockdown).unused_capacity
}

pub fn handle(value: RequestInput) -> ResponseOutput {
    calculate(
        value.arriving_hikers,
        value.injured_hikers,
        value.heater_packs,
        value.storm_lockdown,
    )
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_shelter_unused(a: i64, i: i64, p: i64, storm_lockdown: i32) -> i64 {
    unused(a, i, p, storm_lockdown != 0)
}

