export type RequestInput={arriving_hikers:number;injured_hikers:number;heater_packs:number;storm_lockdown:boolean};export const unused=(a:number,i:number,p:number,s:boolean)=>{const b=a*3+i*6,r=b;return Math.max(p*8-Math.min(r,p*8),0)};export const handle=(v:RequestInput)=>{const b=v.arriving_hikers*3+v.injured_hikers*6,x=v.storm_lockdown?v.heater_packs*2:0,r=Math.max(b-x,0),c=v.heater_packs*8,u=unused(v.arriving_hikers,v.injured_hikers,v.heater_packs,v.storm_lockdown),d=c-u,g=Math.max(r-d,0);return {hiker_total:v.arriving_hikers+v.injured_hikers,baseline_warmth:b,lockdown_reduction:x,required_warmth:r,pack_capacity:c,delivered_warmth:d,uncovered_warmth:g,unused_capacity:u,shelter_state:g===0?'covered':v.storm_lockdown?'storm_gap':'supply_gap'}};export async function loadParley(){return {shelter_unused_capacity:(a:number,b:number,c:number,d:boolean)=>BigInt(unused(a,b,c,d))}}
