import { serve } from "@hono/node-server";
import { serveStatic } from "@hono/node-server/serve-static";
import { Hono } from "hono";
import { z } from "zod";
import { handle } from "./logic.js";

declare const process: { env: Record<string, string | undefined> };
const maxBodyBytes = 16_384;
const schema = z.object({ arriving_hikers:z.number().int().nonnegative(), injured_hikers:z.number().int().nonnegative(), heater_packs:z.number().int().nonnegative(), storm_lockdown:z.boolean() }).strict();
const response = (value: unknown, status = 200) => new Response(JSON.stringify(value), { status, headers: { "content-type": "application/json" } });
const error = (code: string, status: number, detail: string) => response({ error: code, detail }, status);
const app = new Hono();

app.get("/status/shelter-ready", () => response({ service: "Rescue Shelter", ready: true }));
