  const lockdownReduction = stormLockdown ? heaterPacks * 2 : 0;
  const requiredWarmth = Math.max(baselineWarmth - lockdownReduction, 0);
  const packCapacity = heaterPacks * 8;
  const deliveredWarmth = Math.min(requiredWarmth, packCapacity);
  return Math.max(packCapacity - deliveredWarmth, 0);
};

export const handle = (value: RequestInput) => {
  const baselineWarmth = value.arriving_hikers * 3 + value.injured_hikers * 6;
  const lockdownReduction = value.storm_lockdown ? value.heater_packs * 2 : 0;
  const requiredWarmth = Math.max(baselineWarmth - lockdownReduction, 0);
  const packCapacity = value.heater_packs * 8;
  const deliveredWarmth = Math.min(requiredWarmth, packCapacity);
  const uncoveredWarmth = Math.max(requiredWarmth - deliveredWarmth, 0);
  const unusedCapacity = unused(
    value.arriving_hikers,
    value.injured_hikers,
    value.heater_packs,
    value.storm_lockdown,
  );

  return {
    hiker_total: value.arriving_hikers + value.injured_hikers,
    baseline_warmth: baselineWarmth,
    lockdown_reduction: lockdownReduction,
    required_warmth: requiredWarmth,
    pack_capacity: packCapacity,
    delivered_warmth: deliveredWarmth,
    uncovered_warmth: uncoveredWarmth,
    unused_capacity: unusedCapacity,
    shelter_state:
      uncoveredWarmth === 0
        ? "covered"
        : value.storm_lockdown
          ? "storm_gap"
          : "supply_gap",
  };
};

export async function loadParley() {
  return {
    shelter_unused_capacity: unused,
  };
}

