export type RequestInput = {
  coral_trays: number;
  algae_trays: number;
  circulation_pumps: number;
  night_cycle: boolean;
};

export const index = (coralTrays: number, algaeTrays: number, pumps: number, nightCycle: boolean) => {
  const baseFlow = coralTrays * 12 + algaeTrays * 7;
  const nightFlush = nightCycle ? pumps * 5 : 0;
  const requiredFlow = baseFlow + nightFlush;
  const capacity = pumps * 20;
  const servedFlow = Math.min(requiredFlow, capacity);
  const overflowFlow = Math.max(requiredFlow - capacity, 0);

  return servedFlow + overflowFlow * 9 + coralTrays * 3;
};

export const handle = (value: RequestInput) => {
  const baseFlow = value.coral_trays * 12 + value.algae_trays * 7;
  const nightFlush = value.night_cycle ? value.circulation_pumps * 5 : 0;
  const requiredFlow = baseFlow + nightFlush;
  const capacity = value.circulation_pumps * 20;
  const servedFlow = Math.min(requiredFlow, capacity);
  const overflowFlow = Math.max(requiredFlow - capacity, 0);

  return {
    nursery_trays: value.coral_trays + value.algae_trays,
    base_flow_liters: baseFlow,
    night_flush_liters: nightFlush,
    required_flow_liters: requiredFlow,
    pump_capacity_liters: capacity,
    served_flow_liters: servedFlow,
    overflow_flow_liters: overflowFlow,
    reef_index: servedFlow + overflowFlow * 9 + value.coral_trays * 3,
    nursery_state: overflowFlow === 0 ? "balanced" : value.night_cycle ? "night_overflow" : "daytime_overflow",
  };
};

export async function loadParley() {
  return {
    reef_nursery_index: (coralTrays: number, algaeTrays: number, pumps: number, nightCycle: boolean) =>
      BigInt(index(coralTrays, algaeTrays, pumps, nightCycle)),
  };
}

