const shelterUnusedCapacity = (arrivingHikers, injuredHikers, heaterPacks, stormLockdown) => {
  const baselineWarmth = arrivingHikers * 3 + injuredHikers * 6;
  const lockdownReduction = stormLockdown ? heaterPacks * 2 : 0;
  const requiredWarmth = Math.max(baselineWarmth - lockdownReduction, 0);
  const packCapacity = heaterPacks * 8;
  const deliveredWarmth = Math.min(requiredWarmth, packCapacity);
  return BigInt(Math.max(packCapacity - deliveredWarmth, 0));
};

export async function loadParley() { return { shelter_unused_capacity: shelterUnusedCapacity }; }

