use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub arriving_hikers: i64,
    pub injured_hikers: i64,
    pub heater_packs: i64,
    pub storm_lockdown: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.arriving_hikers >= 0 && self.injured_hikers >= 0 && self.heater_packs >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub hiker_total: i64,
    pub baseline_warmth: i64,
    pub lockdown_reduction: i64,
    pub required_warmth: i64,
    pub pack_capacity: i64,
    pub delivered_warmth: i64,
    pub uncovered_warmth: i64,
    pub unused_capacity: i64,
    pub shelter_state: String,
}

pub fn unused(arriving_hikers: i64, injured_hikers: i64, heater_packs: i64, storm_lockdown: bool) -> i64 {
    let baseline_warmth = arriving_hikers * 3 + injured_hikers * 6;
    let lockdown_reduction = if storm_lockdown { heater_packs * 2 } else { 0 };
    let required_warmth = (baseline_warmth - lockdown_reduction).max(0);
    let pack_capacity = heater_packs * 8;
    let delivered_warmth = required_warmth.min(pack_capacity);
    (pack_capacity - delivered_warmth).max(0)
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let baseline_warmth = v.arriving_hikers * 3 + v.injured_hikers * 6;
    let lockdown_reduction = if v.storm_lockdown { v.heater_packs * 2 } else { 0 };
    let required_warmth = (baseline_warmth - lockdown_reduction).max(0);
    let pack_capacity = v.heater_packs * 8;
    let delivered_warmth = required_warmth.min(pack_capacity);
    let uncovered_warmth = (required_warmth - delivered_warmth).max(0);
    let unused_capacity = (pack_capacity - delivered_warmth).max(0);
    let shelter_state = if uncovered_warmth == 0 {
        "covered"
    } else if v.storm_lockdown {
        "storm_gap"
    } else {
        "supply_gap"
    };

    ResponseOutput {
        hiker_total: v.arriving_hikers + v.injured_hikers,
        baseline_warmth,
        lockdown_reduction,
        required_warmth,
        pack_capacity,
        delivered_warmth,
        uncovered_warmth,
        unused_capacity,
        shelter_state: shelter_state.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_shelter_unused(a: i64, b: i64, c: i64, d: i32) -> i64 {
    unused(a, b, c, d != 0)
}

