const reefNurseryIndex = (coralTrays, algaeTrays, circulationPumps, nightCycle) => {
  const baseFlowLiters = coralTrays * 12n + algaeTrays * 7n;
  const nightFlushLiters = nightCycle ? circulationPumps * 5n : 0n;
  const requiredFlowLiters = baseFlowLiters + nightFlushLiters;
  const pumpCapacityLiters = circulationPumps * 20n;
  const servedFlowLiters = requiredFlowLiters < pumpCapacityLiters
    ? requiredFlowLiters
    : pumpCapacityLiters;
  const overflowFlowLiters = requiredFlowLiters > pumpCapacityLiters
    ? requiredFlowLiters - pumpCapacityLiters
    : 0n;
  return servedFlowLiters + overflowFlowLiters * 9n + coralTrays * 3n;
};
export async function loadParley() { return { reef_nursery_index: reefNurseryIndex }; }

