const reefNurseryIndex = (coralTrays, algaeTrays, circulationPumps, nightCycle) => {
  const baseFlowLiters = coralTrays * 12 + algaeTrays * 7;
  const nightFlushLiters = nightCycle ? circulationPumps * 5 : 0;
  const requiredFlowLiters = baseFlowLiters + nightFlushLiters;
  const pumpCapacityLiters = circulationPumps * 20;
  const servedFlowLiters = Math.min(requiredFlowLiters, pumpCapacityLiters);
  const overflowFlowLiters = Math.max(requiredFlowLiters - pumpCapacityLiters, 0);

  return servedFlowLiters + overflowFlowLiters * 9 + coralTrays * 3;
};

