export type RequestInput = {
  public_talks: number;
  research_tracks: number;
  dome_sections: number;
  cloud_monitoring: boolean;
};

export const score = (
  publicTalks: number,
  researchTracks: number,
  domeSections: number,
  cloudMonitoring: boolean,
) => {
  const sessionTotal = publicTalks + researchTracks;
  const openMinutes = publicTalks * 22 + researchTracks * 31;
  const weatherMinutes = cloudMonitoring ? domeSections * 7 : 0;
  const scheduledMinutes = openMinutes + weatherMinutes;
  const staffMinutes = scheduledMinutes * domeSections;
  const restBreaks = Math.floor(scheduledMinutes / 90);

  return staffMinutes + restBreaks * 13 + sessionTotal * 5;
};

export const handle = (value: RequestInput) => {
  const openMinutes = value.public_talks * 22 + value.research_tracks * 31;
  const weatherMinutes = value.cloud_monitoring ? value.dome_sections * 7 : 0;
  const scheduledMinutes = openMinutes + weatherMinutes;

  return {
    session_total: value.public_talks + value.research_tracks,
    open_minutes: openMinutes,
    weather_minutes: weatherMinutes,
    scheduled_minutes: scheduledMinutes,
    staff_minutes: scheduledMinutes * value.dome_sections,
    rest_breaks: Math.floor(scheduledMinutes / 90),
    coordination_score: score(
      value.public_talks,
      value.research_tracks,
      value.dome_sections,
      value.cloud_monitoring,
    ),
    observatory_mode:
      value.research_tracks > value.public_talks
        ? "research_first"
        : value.public_talks > 0
          ? "outreach"
          : "standby",
  };
};

export async function loadParley() {
  return {
    observatory_coordination_score: (
      publicTalks: number,
      researchTracks: number,
      domeSections: number,
      cloudMonitoring: boolean,
    ) =>
      BigInt(
        score(
          publicTalks,
          researchTracks,
          domeSections,
          cloudMonitoring,
        ),
      ),
  };
}

