const shelterUnusedCapacity = (a, i, p, s) => {
  const arrivingHikers = BigInt(a);
  const injuredHikers = BigInt(i);
  const heaterPacks = BigInt(p);
  const baselineWarmth = arrivingHikers * 3n + injuredHikers * 6n;
  const lockdownReduction = s ? heaterPacks * 2n : 0n;
  const requiredWarmth = baselineWarmth > lockdownReduction
    ? baselineWarmth - lockdownReduction
    : 0n;
  const packCapacity = heaterPacks * 8n;
  const deliveredWarmth = requiredWarmth < packCapacity
    ? requiredWarmth
    : packCapacity;
  return packCapacity - deliveredWarmth;
};

export async function loadParley() { return { shelter_unused_capacity: shelterUnusedCapacity }; }

