export type RequestInput = { arriving_hikers: number; injured_hikers: number; heater_packs: number; storm_lockdown: boolean };

export const unused = (arriving: number, injured: number, packs: number, lockdown: boolean) => {
  const baseline = arriving * 3 + injured * 6;
  const required = Math.max(baseline - (lockdown ? packs * 2 : 0), 0);
  const capacity = packs * 8;
  const delivered = Math.min(required, capacity);
  return Math.max(capacity - delivered, 0);
};

export const handle = (value: RequestInput) => {
  const baseline_warmth = value.arriving_hikers * 3 + value.injured_hikers * 6;
  const lockdown_reduction = value.storm_lockdown ? value.heater_packs * 2 : 0;
  const required_warmth = Math.max(baseline_warmth - lockdown_reduction, 0);
  const pack_capacity = value.heater_packs * 8;
  const delivered_warmth = Math.min(required_warmth, pack_capacity);
  const uncovered_warmth = Math.max(required_warmth - delivered_warmth, 0);
  const unused_capacity = Math.max(pack_capacity - delivered_warmth, 0);

  return {
    hiker_total: value.arriving_hikers + value.injured_hikers,
    baseline_warmth,
    lockdown_reduction,
    required_warmth,
    pack_capacity,
    delivered_warmth,
    uncovered_warmth,
    unused_capacity,
    shelter_state: uncovered_warmth === 0 ? "covered" : value.storm_lockdown ? "storm_gap" : "supply_gap",
  };
};

export async function loadParley() {
  return { shelter_unused_capacity: unused };
}

