function observatoryCoordinationScore(publicTalks, researchTracks, domeSections, cloudMonitoring) {
  const sessionTotal = publicTalks + researchTracks;
  const openMinutes = publicTalks * 22 + researchTracks * 31;
  const weatherMinutes = cloudMonitoring ? domeSections * 7 : 0;
  const scheduledMinutes = openMinutes + weatherMinutes;
  const staffMinutes = scheduledMinutes * domeSections;
  const restBreaks = Math.floor(scheduledMinutes / 90);
  return staffMinutes + restBreaks * 13 + sessionTotal * 5;
}

