use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub coral_trays: i64,
    pub algae_trays: i64,
    pub circulation_pumps: i64,
    pub night_cycle: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.coral_trays >= 0 && self.algae_trays >= 0 && self.circulation_pumps >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub nursery_trays: i64,
    pub base_flow_liters: i64,
    pub night_flush_liters: i64,
    pub required_flow_liters: i64,
    pub pump_capacity_liters: i64,
    pub served_flow_liters: i64,
    pub overflow_flow_liters: i64,
    pub reef_index: i64,
    pub nursery_state: String,
}

pub fn index(coral_trays: i64, algae_trays: i64, circulation_pumps: i64, night_cycle: bool) -> i64 {
    let base_flow_liters = coral_trays * 12 + algae_trays * 7;
    let night_flush_liters = if night_cycle { circulation_pumps * 5 } else { 0 };
    let required_flow_liters = base_flow_liters + night_flush_liters;
    let pump_capacity_liters = circulation_pumps * 20;
    let served_flow_liters = required_flow_liters.min(pump_capacity_liters);
    let overflow_flow_liters = (required_flow_liters - pump_capacity_liters).max(0);

    served_flow_liters + overflow_flow_liters * 9 + coral_trays * 3
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let base_flow_liters = v.coral_trays * 12 + v.algae_trays * 7;
    let night_flush_liters = if v.night_cycle { v.circulation_pumps * 5 } else { 0 };
    let required_flow_liters = base_flow_liters + night_flush_liters;
    let pump_capacity_liters = v.circulation_pumps * 20;
    let served_flow_liters = required_flow_liters.min(pump_capacity_liters);
    let overflow_flow_liters = (required_flow_liters - pump_capacity_liters).max(0);
    let nursery_state = if overflow_flow_liters == 0 {
        "balanced"
    } else if v.night_cycle {
        "night_overflow"
    } else {
        "daytime_overflow"
    };

    ResponseOutput {
        nursery_trays: v.coral_trays + v.algae_trays,
        base_flow_liters,
        night_flush_liters,
        required_flow_liters,
        pump_capacity_liters,
        served_flow_liters,
        overflow_flow_liters,
        reef_index: served_flow_liters + overflow_flow_liters * 9 + v.coral_trays * 3,
        nursery_state: nursery_state.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_reef_index(a: i64, b: i64, c: i64, d: i32) -> i64 {
    index(a, b, c, d != 0)
}

